        text: 'Offset (LIMIT 20 OFFSET 100000): database must scan and discard 100,000 rows (O(N) degradation & phantom row shifts). Cursor (WHERE id > last_seen_id ORDER BY id ASC LIMIT 20): utilizes B-Tree index for O(1) constant-time seeks regardless of dataset depth.',
