      'What are standard Log Levels (fatal, error, warn, info, debug, trace), and when should each level be used in application code?',
      'What is a Request Correlation ID (x-request-id), and how does AsyncLocalStorage in Node.js enable tracing a single request across multiple functions and database calls without prop drilling?',
      'What is the difference between /health/live (Liveness probe) and /health/ready (Readiness probe) in Kubernetes and cloud orchestrators?',
      'How do you debug an active Node.js memory leak using Heap Snapshots and the Chrome DevTools Inspector?',
      'What is the difference between Operational Errors (predictable runtime failures like invalid inputs or network timeouts) and Programmer Errors (bugs, null pointer exceptions), and how should each be handled?',
      'What are the Golden Signals of Monitoring (Latency, Traffic, Errors, Saturation), and how do metrics (Prometheus) differ from logs and distributed traces (OpenTelemetry)?',
      'Scenario: A production API experiences an intermittent spike in latency (p99 goes from 50ms to 4000ms), but CPU and memory usage remain low. What step-by-step methodology do you follow to find the root cause?',
