      'Explain how the browser rendering pipeline works from receiving HTML bytes to painting pixels (DOM, CSSOM, Render Tree, Layout, Paint, Composite).',
      'What are the core differences between CSS Flexbox and CSS Grid, and in what real-world UI layout scenarios would you choose one over the other?',
      'How does the JavaScript Event Loop coordinate the Call Stack, Microtask Queue (Promises, MutationObserver), and Macrotask Queue (setTimeout, setInterval, I/O)?',
      'What is the difference between event bubbling, event capturing, and event delegation? Provide a code example where event delegation optimizes memory in a long list.',
      'Explain how closures work in JavaScript and how they can accidentally lead to memory leaks if event listeners or timer references are not cleaned up.',
      'How does Promise.all() differ from Promise.allSettled(), Promise.race(), and Promise.any()? When would you use each in full-stack data fetching?',
      'What are Semantic HTML elements (e.g. <main>, <nav>, <article>, <section>), and how do they impact accessibility (a11y) and SEO compared to <div> soup?',
      'How do you implement focus trapping and keyboard accessibility (Esc to close, Tab / Shift+Tab cycling) in an accessible custom Modal Dialog?',
