      'How do you structure a production GitHub Actions CI pipeline with parallel jobs for linting, TypeScript typechecking, Vitest unit tests, and Supertest integration tests?',
      'How does GitHub Actions cache dependencies (actions/cache or setup-node caching package-lock.json) and Docker layers to speed up CI execution times?',
      'How do you securely manage environment secrets in GitHub Actions (Repository Secrets, Environment Secrets) and prevent them from leaking into build logs?',
      'Explain how to build and publish multi-arch Docker container images to GitHub Container Registry (GHCR) with semantic version tags on Git releases.',
      'Compare deploying a Next.js frontend on Vercel vs AWS Amplify vs Docker containers on Render/AWS ECS. What are the performance and cost trade-offs?',
      'Explain deployment strategies: Blue-Green Deployments vs Rolling Updates vs Canary Releases. How does each minimize downtime and reduce blast radius?',
